head.b:skin:
/* Variable definitions
<Group description="Colors" selector="body">
<Variable name="keycolor" description="Accent color" type="color" default="#e11d48" value="#e11d48"/>
<Variable name="page.background" description="Page background" type="color" default="#f8fafc" value="#f8fafc"/>
<Variable name="header.background" description="Header background" type="color" default="#0f172a" value="#0f172a"/>
</Group>
*/

/* Pulse - visual card-grid theme for photo and magazine blogs.
   Zero JS, zero external requests, mobile-first. */

:root{
  --accent:$(keycolor);
  --bg:$(page.background);
  --header-bg:$(header.background);
  --text:#1e293b;
  --muted:#64748b;
  --border:#e2e8f0;
  --card:#ffffff;
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{
  margin:0;
  background:var(--bg);
  color:var(--text);
  font:1rem/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
.wrap{max-width:64rem;margin-inline:auto;padding-inline:1rem}
a{color:var(--accent);text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;height:auto}

.site-header{background:var(--header-bg);color:#f8fafc;padding-block:1.25rem}
.header-inner{display:flex;flex-wrap:wrap;align-items:center;gap:.5rem 1.5rem}
.site-title{font-size:1.375rem;font-weight:800;letter-spacing:-.02em;line-height:1.2;margin:0}
.site-title a{color:#ffffff}
.pages-section ul{display:flex;flex-wrap:wrap;gap:0 1.25rem;list-style:none;margin:0;padding:0}
.pages-section a{color:#cbd5e1;font-size:.9375rem}
.pages-section a:hover{color:#ffffff}
.search-form{margin-inline-start:auto}
.search-form input{
  max-width:10rem;padding:.375rem .625rem;font:inherit;
  border:1px solid #334155;border-radius:.375rem;background:#1e293b;color:#f8fafc;
}
.search-form input::placeholder{color:#94a3b8}

.site-main{padding-block:1.5rem 2.5rem}
.results-note{color:var(--muted);font-size:.9375rem}

/* Card grid on index/archive/search pages */
body.index .main-section .widget-content,
body.archive .main-section .widget-content{
  display:grid;grid-template-columns:1fr;gap:1.25rem;
}
.post-summary{
  display:flex;flex-direction:column;
  background:var(--card);border:1px solid var(--border);border-radius:.75rem;
  padding:1rem;
}
.post-thumb{display:block;margin:-1rem -1rem .75rem}
.post-thumb img{
  display:block;width:100%;aspect-ratio:16/9;object-fit:cover;
  border-radius:.75rem .75rem 0 0;
}
.post-title{font-size:1.25rem;line-height:1.3;margin:.25rem 0}
.post-title a{color:inherit}
.post-meta{color:var(--muted);font-size:.8125rem;margin:.25rem 0 .5rem}
.post-snippet{color:#475569;font-size:.9375rem}
.read-more{margin-top:auto;padding-top:.5rem;font-weight:700}
.pager{grid-column:1/-1;display:flex;justify-content:space-between;gap:1rem;padding-block:1rem}
.pager a{font-weight:700}

/* Full post */
.post-full{
  max-width:44rem;margin-inline:auto;background:var(--card);
  border:1px solid var(--border);border-radius:.75rem;padding:1.25rem;
}
.post-full .post-title{font-size:2rem;line-height:1.2;margin-top:0}
.post-full .post-meta{margin-bottom:1rem}
.post-labels a{display:inline-block;margin-inline-start:.5rem}
.post-body{overflow-wrap:break-word}
.post-body img{border-radius:.5rem}
.post-body blockquote{
  margin-inline:0;padding-inline-start:1rem;
  border-inline-start:3px solid var(--accent);color:var(--muted);
}
.post-body pre{overflow-x:auto;padding:1rem;background:#0f172a;color:#e2e8f0;border-radius:.5rem;font-size:.9em}
.post-body table{border-collapse:collapse;display:block;overflow-x:auto}
.post-body th,.post-body td{border:1px solid var(--border);padding:.4rem .7rem}

.comments{margin-top:2rem;max-width:44rem;margin-inline:auto}
.comment-form input[type="text"],.comment-form textarea{max-width:100%}
#comment-editor{width:100% !important;max-width:100%}

.site-footer{
  background:var(--header-bg);color:#94a3b8;
  font-size:.875rem;padding-block:1.5rem;text-align:center;
}
.site-footer a{color:#cbd5e1}

@media (min-width:40rem){
  body.index .main-section .widget-content,
  body.archive .main-section .widget-content{grid-template-columns:1fr 1fr}
  .post-full{padding:2rem}
}
@media (min-width:64rem){
  body.index .main-section .widget-content,
  body.archive .main-section .widget-content{grid-template-columns:1fr 1fr 1fr}
  .post-full .post-title{font-size:2.25rem}
}
